//! The C runtime prelude emitted at the top of every generated file.
//! Everything here is standard C11: no compiler builtins, no signed-overflow UB.

const HEAD: &str = r#"/* generated by eider; portable C11 */
#include <stdint.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <setjmp.h>
#include <time.h>
#include <string.h>

static _Thread_local jmp_buf *ei_jb = 0;
#if defined(__GNUC__)
#define ei_unreachable() __builtin_unreachable()
#else
#define ei_unreachable() ((void)0)
#endif
static const char *ei_file = "";

_Noreturn static void ei_trap(const char *msg, int line) {
  fflush(stdout);
  if (ei_jb) {
    printf("FAILED\n    %s (%s:%d)\n", msg, ei_file, line);
    fflush(stdout);
    longjmp(*ei_jb, 1);
  }
  fprintf(stderr, "eider: runtime error: %s (%s:%d)\n", msg, ei_file, line);
  exit(101);
}

static inline uint64_t ei_idx(uint64_t i, uint64_t n, int line) {
  if (i >= n) ei_trap("index out of bounds", line);
  return i;
}

static inline int64_t ei_s2s(int64_t v, int64_t lo, int64_t hi, int l) { if (v < lo || v > hi) ei_trap("integer conversion out of range", l); return v; }
static inline uint64_t ei_s2u(int64_t v, uint64_t hi, int l) { if (v < 0 || (uint64_t)v > hi) ei_trap("integer conversion out of range", l); return (uint64_t)v; }
static inline int64_t ei_u2s(uint64_t v, int64_t hi, int l) { if (v > (uint64_t)hi) ei_trap("integer conversion out of range", l); return (int64_t)v; }
static inline uint64_t ei_u2u(uint64_t v, uint64_t hi, int l) { if (v > hi) ei_trap("integer conversion out of range", l); return v; }

static void *ei_alloc(uint64_t n) {
  void *p = malloc(n ? n : 1);
  if (!p) ei_trap("out of memory", 0);
  return p;
}

typedef struct { char *p; uint64_t len; } ei_String;
static ei_String ei_str_from(const char *s) {
  ei_String r; r.len = (uint64_t)strlen(s); r.p = (char *)ei_alloc(r.len + 1); memcpy(r.p, s, r.len + 1); return r;
}
static ei_String ei_str_from_i64(int64_t v) {
  char buf[32]; snprintf(buf, sizeof buf, "%lld", (long long)v); return ei_str_from(buf);
}
static void ei_drop_String(ei_String *s) { free(s->p); s->p = NULL; s->len = 0; }
static ei_String ei_clone_String(const ei_String *s) {
  ei_String r; r.len = s->len; r.p = (char *)ei_alloc(r.len + 1); memcpy(r.p, s->p, r.len + 1); return r;
}
static void ei_str_cat(ei_String *s, const char *t, uint64_t tl) {
  char *n = (char *)ei_alloc(s->len + tl + 1);
  if (s->len) memcpy(n, s->p, s->len);
  if (tl) memcpy(n + s->len, t, tl);
  n[s->len + tl] = 0;
  free(s->p); s->p = n; s->len += tl;
}
static void ei_str_push(ei_String *s, const char *t) { ei_str_cat(s, t, (uint64_t)strlen(t)); }
static void ei_str_append(ei_String *s, const ei_String *t) { ei_str_cat(s, t->p, t->len); }
static uint64_t ei_hash_u64(uint64_t x) {
  x ^= x >> 33; x *= 0xff51afd7ed558ccdULL; x ^= x >> 33; x *= 0xc4ceb9fe1a85ec53ULL; x ^= x >> 33; return x;
}
static uint64_t ei_hash_str(const char *s) {
  uint64_t h = 1469598103934665603ULL;
  while (*s) { h ^= (unsigned char)*s++; h *= 1099511628211ULL; }
  return ei_hash_u64(h);
}

static void ei_print_i(long long v) { printf("%lld\n", v); }
static void ei_print_u(unsigned long long v) { printf("%llu\n", v); }
static void ei_print_b(bool v) { printf("%s\n", v ? "true" : "false"); }
static void ei_print_s(const char *v) { printf("%s\n", v); }
static uint64_t ei_now_ms(void) { return (uint64_t)((double)clock() * 1000.0 / (double)CLOCKS_PER_SEC); }
"#;

/// Small signed type computed in int64_t (i32).
const SMALL_SIGNED: &str = r#"
static inline T ei_add_N(T a, T b, int l) { int64_t r = (int64_t)a + (int64_t)b; if (r < MIN || r > MAX) ei_trap("integer overflow in +", l); return (T)r; }
static inline T ei_sub_N(T a, T b, int l) { int64_t r = (int64_t)a - (int64_t)b; if (r < MIN || r > MAX) ei_trap("integer overflow in -", l); return (T)r; }
static inline T ei_mul_N(T a, T b, int l) { int64_t r = (int64_t)a * (int64_t)b; if (r < MIN || r > MAX) ei_trap("integer overflow in *", l); return (T)r; }
static inline T ei_div_N(T a, T b, int l) { if (b == 0) ei_trap("division by zero", l); if (a == MIN && b == -1) ei_trap("integer overflow in /", l); return (T)(a / b); }
static inline T ei_rem_N(T a, T b, int l) { if (b == 0) ei_trap("remainder by zero", l); if (a == MIN && b == -1) ei_trap("integer overflow in %", l); return (T)(a % b); }
static inline T ei_neg_N(T a, int l) { if (a == MIN) ei_trap("integer overflow in negation", l); return (T)(-a); }
static inline T ei_wadd_N(T a, T b) { return (T)((uint64_t)a + (uint64_t)b); }
static inline T ei_wsub_N(T a, T b) { return (T)((uint64_t)a - (uint64_t)b); }
static inline T ei_wmul_N(T a, T b) { return (T)((uint64_t)a * (uint64_t)b); }
"#;

/// Small unsigned types computed in uint64_t (u8, u32).
const SMALL_UNSIGNED: &str = r#"
static inline T ei_add_N(T a, T b, int l) { uint64_t r = (uint64_t)a + (uint64_t)b; if (r > MAX) ei_trap("integer overflow in +", l); return (T)r; }
static inline T ei_sub_N(T a, T b, int l) { if (a < b) ei_trap("integer overflow in -", l); return (T)(a - b); }
static inline T ei_mul_N(T a, T b, int l) { uint64_t r = (uint64_t)a * (uint64_t)b; if (r > MAX) ei_trap("integer overflow in *", l); return (T)r; }
static inline T ei_div_N(T a, T b, int l) { if (b == 0) ei_trap("division by zero", l); return (T)(a / b); }
static inline T ei_rem_N(T a, T b, int l) { if (b == 0) ei_trap("remainder by zero", l); return (T)(a % b); }
static inline T ei_wadd_N(T a, T b) { return (T)((uint64_t)a + (uint64_t)b); }
static inline T ei_wsub_N(T a, T b) { return (T)((uint64_t)a - (uint64_t)b); }
static inline T ei_wmul_N(T a, T b) { return (T)((uint64_t)a * (uint64_t)b); }
"#;

const I64: &str = r#"
static inline int64_t ei_add_i64(int64_t a, int64_t b, int l) { if ((b > 0 && a > INT64_MAX - b) || (b < 0 && a < INT64_MIN - b)) ei_trap("integer overflow in +", l); return a + b; }
static inline int64_t ei_sub_i64(int64_t a, int64_t b, int l) { if ((b < 0 && a > INT64_MAX + b) || (b > 0 && a < INT64_MIN + b)) ei_trap("integer overflow in -", l); return a - b; }
static inline int64_t ei_mul_i64(int64_t a, int64_t b, int l) {
  if (a > 0) { if (b > 0) { if (a > INT64_MAX / b) ei_trap("integer overflow in *", l); } else { if (b < INT64_MIN / a) ei_trap("integer overflow in *", l); } }
  else { if (b > 0) { if (a < INT64_MIN / b) ei_trap("integer overflow in *", l); } else { if (a != 0 && b < INT64_MAX / a) ei_trap("integer overflow in *", l); } }
  return a * b;
}
static inline int64_t ei_div_i64(int64_t a, int64_t b, int l) { if (b == 0) ei_trap("division by zero", l); if (a == INT64_MIN && b == -1) ei_trap("integer overflow in /", l); return a / b; }
static inline int64_t ei_rem_i64(int64_t a, int64_t b, int l) { if (b == 0) ei_trap("remainder by zero", l); if (a == INT64_MIN && b == -1) ei_trap("integer overflow in %", l); return a % b; }
static inline int64_t ei_neg_i64(int64_t a, int l) { if (a == INT64_MIN) ei_trap("integer overflow in negation", l); return -a; }
static inline int64_t ei_wadd_i64(int64_t a, int64_t b) { return (int64_t)((uint64_t)a + (uint64_t)b); }
static inline int64_t ei_wsub_i64(int64_t a, int64_t b) { return (int64_t)((uint64_t)a - (uint64_t)b); }
static inline int64_t ei_wmul_i64(int64_t a, int64_t b) { return (int64_t)((uint64_t)a * (uint64_t)b); }
"#;

const U64: &str = r#"
static inline uint64_t ei_add_u64(uint64_t a, uint64_t b, int l) { if (a > UINT64_MAX - b) ei_trap("integer overflow in +", l); return a + b; }
static inline uint64_t ei_sub_u64(uint64_t a, uint64_t b, int l) { if (a < b) ei_trap("integer overflow in -", l); return a - b; }
static inline uint64_t ei_mul_u64(uint64_t a, uint64_t b, int l) { if (a != 0 && b > UINT64_MAX / a) ei_trap("integer overflow in *", l); return a * b; }
static inline uint64_t ei_div_u64(uint64_t a, uint64_t b, int l) { if (b == 0) ei_trap("division by zero", l); return a / b; }
static inline uint64_t ei_rem_u64(uint64_t a, uint64_t b, int l) { if (b == 0) ei_trap("remainder by zero", l); return a % b; }
static inline uint64_t ei_wadd_u64(uint64_t a, uint64_t b) { return a + b; }
static inline uint64_t ei_wsub_u64(uint64_t a, uint64_t b) { return a - b; }
static inline uint64_t ei_wmul_u64(uint64_t a, uint64_t b) { return a * b; }
"#;

fn inst(tpl: &str, n: &str, t: &str, min: &str, max: &str) -> String {
    tpl.replace("ei_add_N", &format!("ei_add_{}", n))
        .replace("ei_sub_N", &format!("ei_sub_{}", n))
        .replace("ei_mul_N", &format!("ei_mul_{}", n))
        .replace("ei_div_N", &format!("ei_div_{}", n))
        .replace("ei_rem_N", &format!("ei_rem_{}", n))
        .replace("ei_neg_N", &format!("ei_neg_{}", n))
        .replace("ei_wadd_N", &format!("ei_wadd_{}", n))
        .replace("ei_wsub_N", &format!("ei_wsub_{}", n))
        .replace("ei_wmul_N", &format!("ei_wmul_{}", n))
        .replace("(T ", &format!("({} ", t))
        .replace(" T ", &format!(" {} ", t))
        .replace("(T)", &format!("({})", t))
        .replace("MIN", min)
        .replace("MAX", max)
}

pub const THREADS_HEAD: &str = "#include <pthread.h>\n#include <stdatomic.h>\n";

pub fn prelude() -> String {
    let mut s = String::from(HEAD);
    s.push_str(&inst(SMALL_SIGNED, "i32", "int32_t", "INT32_MIN", "INT32_MAX"));
    s.push_str(&inst(SMALL_UNSIGNED, "u8", "uint8_t", "0", "UINT8_MAX"));
    s.push_str(&inst(SMALL_UNSIGNED, "u32", "uint32_t", "0", "UINT32_MAX"));
    s.push_str(I64);
    s.push_str(U64);
    s
}

/// Eider-source prelude: parsed and checked together with the user's program.
pub const EIDER_PRELUDE: &str = r#"type Option[T] = | Some(value: T) | None
type Result[T, E] = | Ok(value: T) | Err(error: E)

impl[T] Option[T] {
    fn is_some(self) -> bool {
        match self {
            Some(_) => true
            None => false
        }
    }
    fn is_none(self) -> bool {
        match self {
            Some(_) => false
            None => true
        }
    }
    fn unwrap_or(self, default: T) -> T {
        match self {
            Some(v) => v
            None => default
        }
    }
    fn unwrap(self) -> T {
        match self {
            Some(v) => v
            None => panic("called `unwrap` on a None value")
        }
    }
    fn map[U](self, f: fn(T) -> U) -> Option[U] {
        match self {
            Some(v) => Some(f(v))
            None => None
        }
    }
    fn and_then[U](self, f: fn(T) -> Option[U]) -> Option[U] {
        match self {
            Some(v) => f(v)
            None => None
        }
    }
    fn ok_or[E](self, err: E) -> Result[T, E] {
        match self {
            Some(v) => Ok(v)
            None => Err(err)
        }
    }
}

impl[T, E] Result[T, E] {
    fn is_ok(self) -> bool {
        match self {
            Ok(_) => true
            Err(_) => false
        }
    }
    fn is_err(self) -> bool {
        match self {
            Ok(_) => false
            Err(_) => true
        }
    }
    fn unwrap_or(self, default: T) -> T {
        match self {
            Ok(v) => v
            Err(_) => default
        }
    }
    fn unwrap(self) -> T {
        match self {
            Ok(v) => v
            Err(_) => panic("called `unwrap` on an Err value")
        }
    }
    fn map[U](self, f: fn(T) -> U) -> Result[U, E] {
        match self {
            Ok(v) => Ok(f(v))
            Err(e) => Err(e)
        }
    }
    fn map_err[F](self, f: fn(E) -> F) -> Result[T, F] {
        match self {
            Ok(v) => Ok(v)
            Err(e) => Err(f(e))
        }
    }
    fn and_then[U](self, f: fn(T) -> Result[U, E]) -> Result[U, E] {
        match self {
            Ok(v) => f(v)
            Err(e) => Err(e)
        }
    }
    fn ok(self) -> Option[T] {
        match self {
            Ok(v) => Some(v)
            Err(_) => None
        }
    }
}
"#;
